(24,	1,	'2026-07-05 12:43:22',	'2026-07-05 10:43:22',	'@media (max-width: 768px) {\n  .site-header {\n    position: sticky !important;\n    top: 0 !important;\n    z-index: 999 !important;\n  }\n}\nhtml {\n  overflow-x: hidden;\n}\nbody {\n  overflow-x: visible !important;\n}\n\n@media (max-width: 768px) {\n  .site-header.element-is-sticky {\n    background-color: #ffffff !important;\n  }\n  .site-header.element-is-sticky .menu-link,\n  .site-header.element-is-sticky .ast-mobile-menu-trigger-minimal {\n    color: #000000 !important;\n  }\n  .site-header.element-is-sticky .ast-mobile-svg {\n    fill: #000000 !important;\n  }\n}\n@media (max-width: 768px) {\n  .site-header #ast-desktop-header {\n    display: none !important;\n  }\n}\n@media (max-width: 768px) {\n  .sticky-element-placeholder {\n    background-color: transparent !important;\n  }\n}\n@media (max-width: 768px) {\n  .sticky-element-placeholder {\n    display: none !important;\n  }\n}',	'astra',	'',	'publish',	'closed',	'closed',	'',	'astra',	'',	'',	'2026-07-24 19:38:46',	'2026-07-24 17:38:46',	'',	0,	'http://coffeebar.local/astra/',	0,	'custom_css',	'',	0),
